import{_ as i,o as e,c as t,a2 as r}from"./chunks/framework.LX5S0jbT.js";const c=JSON.parse('{"title":"Pi","description":"","frontmatter":{},"headers":[],"relativePath":"zh/index.md","filePath":"zh/index.md"}'),h={name:"zh/index.md"};function l(o,a,n,s,p,m){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="pi" tabindex="-1">Pi <a class="header-anchor" href="#pi" aria-label="Permalink to &quot;Pi&quot;">​</a></h1><p>Pi 是一个可在终端中运行的可扩展 AI agent。给它一个目标和一个工作文件夹，它可以检查文件、运行命令、编辑内容并完成多步任务。</p><p>Pi 可用于软件开发、研究笔记、写作项目、数据文件或业余工作。你可以直接使用 Pi，通过提示词让它适应你的工作流，也可以用 SDK 构建由 Pi 驱动的其他应用。</p><h2 id="开始使用-pi" tabindex="-1">开始使用 Pi <a class="header-anchor" href="#开始使用-pi" aria-label="Permalink to &quot;开始使用 Pi&quot;">​</a></h2><p>初次接触 Pi？按照<a href="./quickstart.html">快速入门</a>安装 Pi、连接模型并完成第一个任务。</p><p>如果已安装 Pi，选择你想做的事情：</p><ul><li><a href="./usage.html">交互式使用 Pi</a>：添加文件、运行命令、指导进行中的工作并导出结果。</li><li><a href="./models.html">选择模型</a>，或连接订阅、API key、本地模型或兼容端点。</li><li><a href="./sessions.html">继续或分支会话</a>：恢复工作或探索另一种方案，而不丢失历史。</li><li><a href="./configuration.html">配置 Pi</a>：设置偏好、工作文件夹、指令和可复用资源。</li><li><a href="./how-pi-works.html">了解 Pi 的工作原理</a>，包括工具、上下文、会话和 agent 循环。</li></ul><h2 id="自定义-pi" tabindex="-1">自定义 Pi <a class="header-anchor" href="#自定义-pi" aria-label="Permalink to &quot;自定义 Pi&quot;">​</a></h2><p>Pi 可以复用提示词、加载专门指令、添加可执行的集成、更改终端界面、连接模型服务，并将这些资源作为包分发。 使用<a href="./quickstart.html#choose-how-to-customize-pi">快速入门的自定义选择器</a>选出满足需求的最小机制。</p><h2 id="自动化或嵌入-pi" tabindex="-1">自动化或嵌入 Pi <a class="header-anchor" href="#自动化或嵌入-pi" aria-label="Permalink to &quot;自动化或嵌入 Pi&quot;">​</a></h2><ul><li>使用 <a href="./cli.html#invocation-and-output">print 模式</a>处理一次性任务和脚本任务。</li><li>使用 <a href="./json.html">JSON 事件流模式</a>消费一次运行的结构化事件。</li><li>使用 <a href="./rpc.html">RPC 模式</a>控制独立的 Pi 进程。</li><li>使用 <a href="./sdk.html">TypeScript SDK</a> 在应用内运行 Pi。</li></ul><h2 id="查找参考和设置信息" tabindex="-1">查找参考和设置信息 <a class="header-anchor" href="#查找参考和设置信息" aria-label="Permalink to &quot;查找参考和设置信息&quot;">​</a></h2><p>使用参考页面查阅 <a href="./cli.html">CLI 选项</a>、<a href="./settings.html">设置</a>、<a href="./providers.html">provider</a>、<a href="./keybindings.html">快捷键</a>和<a href="./environment-variables.html">环境变量</a>。</p><p>平台相关的帮助见<a href="./terminal-setup.html">终端设置</a>、<a href="./windows.html">Windows</a>、<a href="./tmux.html">tmux</a>、<a href="./termux.html">Android 上的 Termux</a>或<a href="./containerization.html">容器化</a>。</p><h2 id="安全使用" tabindex="-1">安全使用 <a class="header-anchor" href="#安全使用" aria-label="Permalink to &quot;安全使用&quot;">​</a></h2><p>Pi 的工具和扩展以 Pi 进程的权限运行。项目信任（project trust）控制 Pi 加载哪些项目资源，但它不会沙箱化工具调用。在使用不受信任的文件、仓库、扩展或无人值守的自动化之前，请先阅读<a href="./security.html">安全</a>。</p>',16)])])}const f=i(h,[["render",l]]);export{c as __pageData,f as default};
